 * line at the offending character, or the line at EOF for an unterminated quote.
 * Count CR and LF inside quoted fields too; each CRLF counts as one newline,
 * regardless of chunk boundaries. A lone CR or LF counts as one newline.
 * end() throws SyntaxError for an unterminated quoted field. No recovery behavior
 * is required after a SyntaxError. Chunk boundaries may otherwise fall anywhere,
 * including inside an escaped '""', CRLF, or a Unicode surrogate pair.
 *
 * options.header does not affect this streaming API: it always yields arrays.
 * @param {{ delimiter?: string, header?: boolean }} [options]
 * @returns {{ push(chunk: string): string[][], end(): string[][] }}
 */
function createParser(options = {}) {
  const delimiter = resolveDelimiter(options);

  let state = FIELD_START;
  let field = '';
  let row = [];
  // True once any character of the current record has been consumed, so end()
  // can tell "no unfinished record" apart from a record of one empty field.
  let rowStarted = false;
  // True when the previous character consumed was CR, in any context. Used to
  // treat CRLF as one separator / one newline even across chunk boundaries.
  let prevCR = false;
  let line = 1;
  let sawInput = false;
  let ended = false;

  function syntaxError(message) {
    return new SyntaxError(`${message} at line ${line}`);
  }

  function endField() {
    row.push(field);
    field = '';
    state = FIELD_START;
  }

  function endRecord(out) {
    endField();
    out.push(row);
    row = [];
    rowStarted = false;
  }

  function push(chunk) {
    if (ended) throw new Error('cannot push after end()');
    if (typeof chunk !== 'string') throw new TypeError('chunk must be a string');
    const out = [];
    if (chunk.length === 0) return out;

    let i = 0;
    if (!sawInput) {
      sawInput = true;
      if (chunk[0] === BOM) i = 1;
    }

    for (; i < chunk.length; i++) {
      const ch = chunk[i];
      const isCR = ch === '\r';
      const isLF = ch === '\n';
      const lfAfterCR = isLF && prevCR;
      if (isCR || (isLF && !prevCR)) line++;
      prevCR = isCR;

      switch (state) {
        case QUOTED:
          if (ch === '"') state = QUOTE_PENDING;
          else field += ch;
          break;

        case QUOTE_PENDING:
          if (ch === '"') {
            field += '"';
            state = QUOTED;
          } else if (ch === delimiter) {
            endField();
          } else if (isCR || isLF) {
            endRecord(out);
          } else {
            throw syntaxError(`unexpected character ${JSON.stringify(ch)} after closing quote`);
          }
          break;

        case FIELD_START:
          // The LF of a CRLF whose CR already completed the record.
          if (lfAfterCR) break;
          rowStarted = true;
          if (ch === '"') state = QUOTED;
          else if (ch === delimiter) endField();
          else if (isCR || isLF) endRecord(out);
          else {
            field = ch;
            state = UNQUOTED;
          }
          break;

        default: // UNQUOTED
          if (ch === delimiter) endField();
          else if (isCR || isLF) endRecord(out);
          else field += ch;
          break;
      }
    }
    return out;
  }

  function end() {
    if (ended) return [];
    ended = true;
    if (state === QUOTED) throw syntaxError('unterminated quoted field');
    const out = [];
    if (rowStarted) endRecord(out);
    return out;
  }

  return { push, end };
}

/**
 * Parse all text using the same grammar and validation as createParser.
 * With options.header === true, convert records with the existing
 * toObjects(records, { header: true }) helper; otherwise return string[][].
 * Empty input yields [] in either mode. Do not change the helper's contract.
 */
function parse(text, options = {}) {
  const parser = createParser(options);
  const records = parser.push(text).concat(parser.end());
  return options.header === true ? toObjects(records, { header: true }) : records;
}

module.exports = { createParser, parse };

